CREATE TABLE aoo_invite_link (invite_id BIGINT NOT NULL AUTO_INCREMENT,token_hash BINARY(32) NOT NULL,kind ENUM('ROOM','CLUB') NOT NULL,target_id BIGINT NOT NULL,issuer_account_id BIGINT NOT NULL,max_uses INT UNSIGNED NOT NULL,use_count INT UNSIGNED NOT NULL DEFAULT 0,expires_at DATETIME(3) NOT NULL,status ENUM('ACTIVE','EXHAUSTED','REVOKED') NOT NULL,created_at DATETIME(3) NOT NULL,last_used_at DATETIME(3) NULL,revoked_at DATETIME(3) NULL,PRIMARY KEY(invite_id),UNIQUE KEY uk_invite_token_hash(token_hash),KEY ix_invite_issuer(issuer_account_id,created_at),KEY ix_invite_target(kind,target_id,status),CONSTRAINT ck_invite_usage CHECK(max_uses BETWEEN 1 AND 10000 AND use_count<=max_uses)) ENGINE=InnoDB;
CREATE TABLE aoo_invite_link_audit (audit_id BIGINT NOT NULL AUTO_INCREMENT,invite_id BIGINT NOT NULL,event_type ENUM('CREATED','PREVIEWED','CONSUMED','REVOKED') NOT NULL,actor_account_id BIGINT NULL,source_channel VARCHAR(64) NOT NULL,source_hash BINARY(32) NULL,outcome ENUM('SUCCESS','REJECTED') NOT NULL,occurred_at DATETIME(3) NOT NULL,PRIMARY KEY(audit_id),KEY ix_invite_audit(invite_id,occurred_at),CONSTRAINT fk_invite_audit_link FOREIGN KEY(invite_id) REFERENCES aoo_invite_link(invite_id)) ENGINE=InnoDB;
CREATE TABLE aoo_invite_consumption (consumption_id BIGINT NOT NULL AUTO_INCREMENT,idempotency_key VARCHAR(128) NOT NULL,invite_id BIGINT NOT NULL,consumer_account_id BIGINT NOT NULL,reward_state ENUM('PENDING','GRANTED') NOT NULL,reward_reference VARCHAR(160) NULL,created_at DATETIME(3) NOT NULL,updated_at DATETIME(3) NOT NULL,PRIMARY KEY(consumption_id),UNIQUE KEY uk_invite_consumption_key(idempotency_key),UNIQUE KEY uk_invite_consumer(invite_id,consumer_account_id),CONSTRAINT fk_invite_consumption_link FOREIGN KEY(invite_id) REFERENCES aoo_invite_link(invite_id)) ENGINE=InnoDB;
